for _ in range(int(input())):
	N = int(input())
	reverse = [0] * N
	diff = 0
	for z in range(N):
		inp = input()
		x = y = 0
		for j in range(N):
			if inp[j] == '1':
				if j < N // 2:
					x += 1
				else:
					y += 1
		diff += x - y
		reverse[z] = -2 * (x - y)
	ans = abs(diff)
	for i in range(N):
		if abs(diff + reverse[i]) < ans:
			ans = abs(diff + reverse[i])
	print(ans)
